{
  "name": "Nobø Ecohub 供暖控制集线器",
  "name_en": "Nobø Ecohub heating control hub",
  "manufacturer": "Nobø",
  "description": "用于 Nobø 电采暖系统的网络集线器，可在局域网中发现并连接供暖分区与组件，管理周程序、舒适/节能/离家等覆盖模式，并读取分区或组件温度，适合实验室房间供暖与环境温度管理。",
  "description_en": "A network-connected hub for Nobø electric heating systems. It can discover and connect heating zones and components on a local network, manage weekly schedules and comfort/eco/away overrides, and read zone or component temperatures for room heating and environmental temperature management in labs.",
  "tag_hints": [
    "electric heating control",
    "zoned heating",
    "weekly scheduling",
    "temperature monitoring",
    "comfort and eco modes",
    "networked hub"
  ],
  "actions": [
    {
      "action_name": "auto-async_add_week_profile",
      "description": "异步添加新的周程序",
      "description_en": "Asynchronously add a new weekly schedule profile"
    },
    {
      "action_name": "auto-async_connect_hub",
      "description": "异步连接到指定的 Ecohub 集线器",
      "description_en": "Asynchronously connect to a specified Ecohub hub"
    },
    {
      "action_name": "auto-async_create_override",
      "description": "异步创建集线器、分区或组件的临时覆盖模式",
      "description_en": "Asynchronously create a temporary override mode for the hub, a zone, or a component"
    },
    {
      "action_name": "auto-async_remove_week_profile",
      "description": "异步删除周程序",
      "description_en": "Asynchronously remove a weekly schedule profile"
    },
    {
      "action_name": "auto-async_send_command",
      "description": "异步向集线器发送命令",
      "description_en": "Asynchronously send commands to the hub"
    },
    {
      "action_name": "auto-async_update_week_profile",
      "description": "异步更新周程序",
      "description_en": "Asynchronously update a weekly schedule profile"
    },
    {
      "action_name": "auto-async_update_zone",
      "description": "异步更新分区设置",
      "description_en": "Asynchronously update zone settings"
    },
    {
      "action_name": "auto-close",
      "description": "关闭与集线器的连接",
      "description_en": "Close the connection to the hub"
    },
    {
      "action_name": "auto-connect",
      "description": "连接到 Ecohub 集线器",
      "description_en": "Connect to the Ecohub hub"
    },
    {
      "action_name": "auto-connect_hub",
      "description": "连接到指定的集线器",
      "description_en": "Connect to a specified hub"
    },
    {
      "action_name": "auto-create_override",
      "description": "创建集线器、分区或组件的临时覆盖模式",
      "description_en": "Create a temporary override mode for the hub, a zone, or a component"
    },
    {
      "action_name": "auto-deregister_callback",
      "description": "取消注册集线器状态更新回调",
      "description_en": "Deregister a hub state update callback"
    },
    {
      "action_name": "auto-keep_alive",
      "description": "发送保活握手以维持集线器连接",
      "description_en": "Send keep-alive handshakes to maintain the hub connection"
    },
    {
      "action_name": "auto-reconnect_hub",
      "description": "重新连接集线器",
      "description_en": "Reconnect to the hub"
    },
    {
      "action_name": "auto-register_callback",
      "description": "注册集线器状态更新回调",
      "description_en": "Register a hub state update callback"
    },
    {
      "action_name": "auto-response_handler",
      "description": "处理并应用集线器返回的状态更新",
      "description_en": "Process and apply status updates returned by the hub"
    },
    {
      "action_name": "auto-send_command",
      "description": "向集线器发送命令",
      "description_en": "Send commands to the hub"
    },
    {
      "action_name": "auto-socket_receive",
      "description": "接收集线器发送的数据和状态消息",
      "description_en": "Receive data and status messages from the hub"
    },
    {
      "action_name": "auto-start",
      "description": "启动集线器通信、保活和数据接收",
      "description_en": "Start hub communication, keep-alive, and data reception"
    },
    {
      "action_name": "auto-stop",
      "description": "停止集线器通信并关闭连接",
      "description_en": "Stop hub communication and close the connection"
    },
    {
      "action_name": "auto-update_zone",
      "description": "更新分区设置",
      "description_en": "Update zone settings"
    },
    {
      "action_name": "auto-discover_hubs",
      "description": "在本地网络中发现 Ecohub 集线器",
      "description_en": "Discover Ecohub hubs on the local network"
    },
    {
      "action_name": "auto-async_discover_hubs",
      "description": "异步在本地网络中发现 Ecohub 集线器",
      "description_en": "Asynchronously discover Ecohub hubs on the local network"
    },
    {
      "action_name": "auto-get_response",
      "description": "获取集线器响应消息",
      "description_en": "Get the hub response message"
    },
    {
      "action_name": "auto-get_week_profile_status",
      "description": "获取周程序在指定时间的状态",
      "description_en": "Get the weekly schedule status at a specified time"
    },
    {
      "action_name": "auto-get_zone_override_mode",
      "description": "获取分区覆盖模式",
      "description_en": "Get the zone override mode"
    },
    {
      "action_name": "auto-get_current_zone_mode",
      "description": "获取当前分区运行模式",
      "description_en": "Get the current zone operating mode"
    },
    {
      "action_name": "auto-get_current_component_temperature",
      "description": "获取组件当前温度",
      "description_en": "Get the current component temperature"
    },
    {
      "action_name": "auto-get_current_zone_temperature",
      "description": "获取当前分区温度",
      "description_en": "Get the current zone temperature"
    },
    {
      "action_name": "auto-is_valid_datetime",
      "description": "验证日期时间格式是否有效",
      "description_en": "Validate whether a date-time value is valid"
    },
    {
      "action_name": "auto-time_is_quarter",
      "description": "检查时间是否位于 15 分钟刻度",
      "description_en": "Check whether a time falls on a 15-minute interval"
    },
    {
      "action_name": "auto-validate_temperature",
      "description": "验证温度设定值是否有效",
      "description_en": "Validate whether a temperature setting is valid"
    },
    {
      "action_name": "auto-validate_week_profile",
      "description": "验证周程序配置是否有效",
      "description_en": "Validate whether a weekly schedule profile is valid"
    },
    {
      "action_name": "auto-model_id",
      "description": "获取设备型号标识",
      "description_en": "Get the device model identifier"
    },
    {
      "action_name": "auto-name",
      "description": "获取设备名称",
      "description_en": "Get the device name"
    },
    {
      "action_name": "auto-type",
      "description": "获取设备类型",
      "description_en": "Get the device type"
    },
    {
      "action_name": "auto-supports_comfort",
      "description": "获取是否支持舒适模式",
      "description_en": "Get whether comfort mode is supported"
    },
    {
      "action_name": "auto-supports_eco",
      "description": "获取是否支持节能模式",
      "description_en": "Get whether eco mode is supported"
    },
    {
      "action_name": "auto-requires_control_panel",
      "description": "获取是否需要控制面板",
      "description_en": "Get whether a control panel is required"
    },
    {
      "action_name": "auto-has_temp_sensor",
      "description": "获取是否带有温度传感器",
      "description_en": "Get whether a temperature sensor is present"
    }
  ]
}

